package it.attendance100.mybicocca.codegen.target.kotlin

import it.attendance100.mybicocca.codegen.core.CodeTarget
import it.attendance100.mybicocca.codegen.core.GeneratedFile
import it.attendance100.mybicocca.codegen.core.TargetContext
import it.attendance100.mybicocca.codegen.core.decodeOptions
import it.attendance100.mybicocca.codegen.core.generatedMarker
import it.attendance100.mybicocca.codegen.model.ApiSpec
import kotlinx.serialization.Serializable

/**
 * Writes the runtime every API generated by [KotlinTarget] builds on: the base class of the
 * modules, the HTTP client and its settings, the policy describing an API's errors and retries,
 * and the base exception. Its spec only names it; see `common/specs/runtime`.
 *
 * The sources are this module's `kotlin-runtime` resources, with their package set to
 * [Options.packageName], which must be the `runtimePackage` of the APIs' kotlin targets.
 */
class KotlinRuntimeTarget : CodeTarget {
    override val id: String = "kotlin-runtime"

    @Serializable
    data class Options(val packageName: String)

    override fun generate(spec: ApiSpec, context: TargetContext): List<GeneratedFile> {
        val options = context.options.decodeOptions<Options>()
        return FILES.map { name ->
            val source = javaClass.getResource("/$RESOURCES/$name")?.readText()?.replace("\r\n", "\n")
                ?: error("Missing runtime resource $name")
            val content = "// ${generatedMarker(spec.id)}. Do not edit.\n" + source.replace(PACKAGE_PLACEHOLDER, options.packageName)
            GeneratedFile("${options.packageName.replace('.', '/')}/$name", content)
        }
    }

    private companion object {
        const val RESOURCES = "kotlin-runtime"
        const val PACKAGE_PLACEHOLDER = "__PACKAGE__"
        val FILES = listOf("ApiException.kt", "RestApi.kt", "RestClient.kt", "RestPolicy.kt")
    }
}
